// HasCredentials applies the HasEdge predicate on the "credentials" edge.
func HasCredentials() predicate.CPAInstance {
	return predicate.CPAInstance(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CredentialsTable, CredentialsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCredentialsWith applies the HasEdge predicate on the "credentials" edge with a given conditions (other predicates).
func HasCredentialsWith(preds ...predicate.CPACredential) predicate.CPAInstance {
	return predicate.CPAInstance(func(s *sql.Selector) {
		step := newCredentialsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CPAInstance) predicate.CPAInstance {
	return predicate.CPAInstance(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CPAInstance) predicate.CPAInstance {
	return predicate.CPAInstance(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CPAInstance) predicate.CPAInstance {
	return predicate.CPAInstance(sql.NotPredicates(p))
}
